// catalog · кейс co-20 (.qa/tests/client-ordering/) — категория, в которой только архивный товар, у клиента не показывается (#899df3e5, עבר QA 2026-10-06).
// Создаёт свои данные: категорию «QA-AUTO-catvis-arch-<ts>» и товар «QA-AUTO-catvis-<ts>» в ней, приход 3 шт. «ללא מקום»
// (появляются движения) → удаление товара уводит его в архив («הוסר מהקטלוג. ההזמנות והתנועות שמזכירות אותו נשמרו.»).
// Побочный эффект (как в inventory/delete-unplaced-stock.spec.ts): архивный товар и запись «קליטה» в «יומן תנועות» остаются навсегда (с #d7b7ec74 удаление записи «מחיקת מוצר» не пишет).
// Селекторы шторки «סינון ומיון» не сверялись в браузере — при первом /qa-regress проверить.
// afterAll: удаляет товар (если не удалён) и категорию QA-AUTO этого прогона. Реальные товары/категории не трогаются.
import { test, expect, Page, Browser } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, `../../../auth/${role}.json`);
test.use({ storageState: auth('admin') });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const CAT = `QA-AUTO-catvis-arch-${TS}`;
const P = `QA-AUTO-catvis-${TS}`;
const SKU = `QA-AUTO-CATVIS-${TS}`;
const QTY = 3;
let productId = '';

const qtyBtn = (page: Page) => page.getByRole('button', { name: `קליטת מלאי — ${P}`, exact: true });
const row = (page: Page) => qtyBtn(page).locator('xpath=ancestor::*[.//button[@aria-label="פעולות"]][1]');
const catRow = (page: Page, name: string) =>
  page.getByText(name, { exact: true }).first().locator('xpath=ancestor::*[.//button[@aria-label="פעולות"]][1]');

async function findProduct(page: Page) {
  await page.goto('/catalog');
  await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 20_000 });
  await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(P);
  await expect(qtyBtn(page).or(page.getByText('לא נמצאו מוצרים התואמים לסינון'))).toBeVisible({ timeout: 20_000 });
}

async function asBuyer<T>(browser: Browser, fn: (page: Page) => Promise<T>): Promise<T> {
  const ctx = await browser.newContext({ storageState: auth('buyer'), locale: 'he-IL' });
  const page = await ctx.newPage();
  try {
    return await fn(page);
  } finally {
    await ctx.close();
  }
}

/** Шторка «סינון ומיון» в /shop (кнопка-иконка рядом с поиском; «נקה סינון» пустого состояния — не она). */
async function openFilterSheet(bp: Page) {
  await bp.getByRole('button', { name: /^(?!נקה).*סינון/ }).first().click();
  const sheet = bp.getByRole('dialog').filter({ hasText: 'סינון ומיון' });
  await expect(sheet).toBeVisible();
  return sheet;
}

async function deleteProductViaMenu(page: Page) {
  await row(page).getByRole('button', { name: 'פעולות' }).click();
  const del = page.getByRole('menuitem', { name: /^מחיקה/ });
  await expect(del).toBeEnabled(); // остаток «ללא מקום» удаление не блокирует (#0309a9bf, #d7b7ec74 — обычное окно)
  await del.click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'מחיקת מוצר' })).toBeVisible();
  await dlg.getByRole('button', { name: 'מחיקה', exact: true }).click();
}

test.describe('catalog — קטגוריה שיש בה רק מוצר בארכיון לא מוצגת ללקוח (#899df3e5)', () => {
  test.afterAll(async ({ browser }) => {
    const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL' });
    const page = await ctx.newPage();
    try {
      await findProduct(page);
      if (await qtyBtn(page).count()) {
        await deleteProductViaMenu(page);
        await expect(page.getByText(/הוסר מהקטלוג|נמחק\./).first()).toBeVisible({ timeout: 15_000 });
      }
      await page.goto('/catalog/categories');
      await expect(page.getByRole('heading', { level: 1, name: 'קטגוריות' })).toBeVisible();
      const label = page.getByText(CAT, { exact: true }).first();
      await expect(label).toBeVisible({ timeout: 20_000 }).catch(() => {});
      if (!(await label.count())) return;
      await catRow(page, CAT).getByRole('button', { name: 'פעולות' }).first().click();
      const item = page.getByRole('menuitem', { name: /^מחיקה/ });
      if (await item.isDisabled()) { await page.keyboard.press('Escape'); return; }
      await item.click();
      await page.getByRole('dialog').getByRole('button', { name: 'מחיקה' }).click();
      await expect(page.getByText(CAT, { exact: true })).toHaveCount(0, { timeout: 15_000 });
    } finally {
      await ctx.close();
    }
  });

  test('הכנה: קטגוריה QA, מוצר QA בקטגוריה, קליטה של 3 «ללא מקום»; הלקוח רואה את הקטגוריה #899df3e5 @desktop', async ({ page, browser }) => {
    await page.goto('/catalog/categories');
    await expect(page.getByRole('heading', { level: 1, name: 'קטגוריות' })).toBeVisible();
    await expect(page.getByText('מצתים', { exact: true }).first()).toBeVisible({ timeout: 20_000 }); // список загружен (иначе загрузка сбрасывает форму)
    await page.getByRole('button', { name: 'קטגוריה חדשה' }).click();
    await page.getByRole('textbox', { name: /שם קטגוריה/ }).fill(CAT);
    await page.getByRole('button', { name: 'שמירה', exact: true }).click();
    await expect(page.getByText(CAT, { exact: true }).first()).toBeVisible();

    await page.goto('/catalog/new');
    await expect(page.getByRole('heading', { level: 1, name: 'מוצר חדש' })).toBeVisible();
    await page.getByRole('textbox', { name: /שם מוצר/ }).fill(P);
    await page.getByRole('textbox', { name: /מק"ט/ }).fill(SKU);
    await page.getByRole('spinbutton', { name: 'מחיר בסיס' }).fill('1');
    await page.getByRole('button', { name: 'שמירה', exact: true }).click();
    await expect(page.getByText('נוסף לקטלוג.')).toBeVisible({ timeout: 15_000 });

    await findProduct(page);
    await page.getByRole('button', { name: P, exact: true }).click();
    await expect(page).toHaveURL(/\/edit$/);
    productId = page.url().match(/catalog\/([0-9a-f-]{36})\/edit/)![1];
    const cb = page.getByRole('combobox', { name: 'קטגוריה' });
    await expect(cb.locator('option', { hasText: CAT })).toHaveCount(1, { timeout: 15_000 });
    await cb.selectOption((await cb.locator('option', { hasText: CAT }).getAttribute('value'))!);
    await page.getByRole('button', { name: 'שמירה', exact: true }).click();
    await expect(page).toHaveURL(/\/catalog$/);

    await findProduct(page);
    await qtyBtn(page).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: 'הוספת פריט למלאי' })).toBeVisible();
    await dlg.getByRole('combobox', { name: 'מקום היעד' }).selectOption({ label: 'ללא מקום — לשיוך בהמשך' });
    await dlg.getByRole('spinbutton', { name: 'כמות', exact: true }).fill(String(QTY));
    await dlg.getByRole('button', { name: 'הוספה' }).click();
    await expect(dlg).toHaveCount(0, { timeout: 15_000 });
    await findProduct(page);
    await expect(qtyBtn(page)).toHaveText(String(QTY), { timeout: 15_000 });
    await expect(row(page)).toContainText(CAT);

    await asBuyer(browser, async (bp) => {
      await bp.goto('/shop');
      await expect(bp.getByRole('button', { name: CAT, exact: true })).toBeVisible({ timeout: 20_000 });
    });
  });

  test('אחרי מחיקת המוצר (ארכיון) הקטגוריה לא מוצגת ללקוח — לא בשבבים ולא בסינון; אצל המפיץ היא נשארת #899df3e5 @desktop', async ({ page, browser }) => {
    test.skip(!productId, 'товар не создан');
    await findProduct(page);
    await deleteProductViaMenu(page);
    // архив, а не полное удаление: у товара есть движения
    await expect(page.getByText(/הוסר מהקטלוג\. ההזמנות והתנועות שמזכירות אותו נשמרו\./)).toBeVisible({ timeout: 15_000 });

    await asBuyer(browser, async (bp) => {
      await bp.goto('/shop');
      // список категорий загружен: реальная категория с товарами на месте (co-03)
      await expect(bp.getByRole('button', { name: 'מצתים', exact: true })).toBeVisible({ timeout: 20_000 });
      await expect(bp.getByRole('button', { name: CAT, exact: true })).toHaveCount(0);
      const sheet = await openFilterSheet(bp);
      await expect(sheet.getByText('מצתים', { exact: true }).first()).toBeVisible();
      await expect(sheet.getByText(CAT, { exact: true })).toHaveCount(0);
    });

    await page.goto('/catalog/categories');
    await expect(page.getByText(CAT, { exact: true }).first()).toBeVisible({ timeout: 20_000 });
  });
});
